// ─── EINSÄTZE (Doodle-Verfügbarkeit pro Spiel) ───────────────────────────────
// Mapping Spielplan-Name (Herren N / Mädchen N) → Aufstellungs-Name (Erwachsene…)
const SPIELPLAN_TO_AUFSTELLUNG = {
  "Herren 1":"Erwachsene I", "Herren 2":"Erwachsene II", "Herren 3":"Erwachsene III",
  "Herren 4":"Erwachsene IV", "Herren 5":"Erwachsene V", "Herren 6":"Erwachsene VI",
  "Mädchen 11":"Mädchen 11", "Mädchen 13":"Mädchen 13", "Mädchen 15":"Mädchen 15",
  "Jugend 11":"Jugend 11",
};
// Umkehrung: Aufstellungs-Name → Spielplan-Name (Erwachsene V → Herren 5).
const AUFSTELLUNG_TO_SPIELPLAN = {
  "Erwachsene I":"Herren 1", "Erwachsene II":"Herren 2", "Erwachsene III":"Herren 3",
  "Erwachsene IV":"Herren 4", "Erwachsene V":"Herren 5", "Erwachsene VI":"Herren 6",
  "Mädchen 11":"Mädchen 11", "Mädchen 13":"Mädchen 13", "Mädchen 15":"Mädchen 15",
  "Jugend 11":"Jugend 11",
};
// Erwachsenen-Mannschaftsnummer aus Aufstellungs-Name (Erwachsene=1, Erwachsene II=2, …)
const ERW_NUM = {"Erwachsene I":1,"Erwachsene II":2,"Erwachsene III":3,"Erwachsene IV":4,"Erwachsene V":5,"Erwachsene VI":6};
// Vereinheitlicht den Aufstellungs-/MF-Namen der 1. Mannschaft: früher wurde sie
// teils "Erwachsene" (ohne Ziffer) genannt, jetzt durchgängig "Erwachsene I".
// Diese Funktion fängt Alt-Werte ab, damit MF-Zuordnung & Co. zuverlässig greifen.
function normAufName(aufName){
  return aufName==="Erwachsene" ? "Erwachsene I" : (aufName||"");
}
function istErwachsenenMannschaft(aufName){ return normAufName(aufName) in ERW_NUM; }
function istNachwuchsMannschaft(aufName){ return /^(Mädchen|Jugend)/.test(aufName); }

// Normalisiere Namen für Vergleich (Aufstellung: "Nachname, Vorname" ↔ player: firstName/lastName)
function normName(s){ return (s||"").toLowerCase().replace(/\s+/g,"").replace(/[.,]/g,""); }
function playerMatchesAufName(player, aufName){
  const a=normName(aufName);
  const full1=normName(`${player.lastName},${player.firstName}`);
  const full2=normName(`${player.firstName}${player.lastName}`);
  const full3=normName(`${player.lastName}${player.firstName}`);
  return a===full1||a===full2||a===full3;
}

// Welche Aufstellungs-Mannschaften sind dem Spieler zugeordnet (aus Aufstellung)?
function teamsOfPlayer(player, aufstellungSpieler){
  const teams=new Set();
  for(const row of aufstellungSpieler){
    if(playerMatchesAufName(player,row.name)) teams.add(normAufName(row.mannschaft));
  }
  return [...teams];
}

// Prüft, ob eine Aufstellungszeile NES trägt (Nachwuchs-Ergänzungsspieler).
function rowHatNES(row){
  if(!row||!row.bem) return false;
  return String(row.bem).split(/[\s,]+/).map(t=>t.trim()).includes("NES");
}

// Mannschaften, in denen der Spieler OHNE NES-Status aufgestellt ist (also seine
// eigentliche Stamm-/Meldemannschaft, nicht bloß als Nachwuchs-Ergänzung).
function teamsOfPlayerOhneNES(player, aufstellungSpieler){
  const teams=new Set();
  for(const row of aufstellungSpieler){
    if(playerMatchesAufName(player,row.name) && !rowHatNES(row)) teams.add(normAufName(row.mannschaft));
  }
  return [...teams];
}

// Die für Spielplan/Kalender vorzuwählende Mannschaft einer eingeloggten Person:
// - Erwachsene: die gemeldete (tiefste) Erwachsenen-Mannschaft = höchste Nummer
//   (Erwachsene spielen in genau einer Mannschaft, höher nur als Ersatz).
// - Nachwuchs/Spieler: die Mannschaft, in der sie OHNE NES aufgestellt sind.
// Rückgabe: Aufstellungs-Mannschaftsname oder "" wenn nicht ermittelbar.
function stammMannschaftVorauswahl(player, aufstellungSpieler){
  if(!player) return "";
  const ohneNES = teamsOfPlayerOhneNES(player, aufstellungSpieler);
  const erwOhne = ohneNES.filter(istErwachsenenMannschaft);
  if(erwOhne.length>0) return erwOhne.sort((a,b)=>ERW_NUM[normAufName(b)]-ERW_NUM[normAufName(a)])[0]; // tiefste = höchste Nummer
  const nwOhne = ohneNES.filter(istNachwuchsMannschaft);
  if(nwOhne.length>0) return nwOhne[0];
  // Fallback: falls nur NES-Meldungen existieren, nimm irgendeine zugeordnete
  const alle = teamsOfPlayer(player, aufstellungSpieler);
  const erwAlle = alle.filter(istErwachsenenMannschaft);
  if(erwAlle.length>0) return erwAlle.sort((a,b)=>ERW_NUM[normAufName(b)]-ERW_NUM[normAufName(a)])[0];
  return alle[0]||"";
}

// Aufstellungs-Rang (z.B. "1.5") eines Spielers in einer bestimmten Mannschaft
function rangOfPlayerInTeam(player, aufName, aufstellungSpieler){
  const ziel=normAufName(aufName);
  for(const row of aufstellungSpieler){
    if(normAufName(row.mannschaft)===ziel && playerMatchesAufName(player,row.name)) return row.rang||"";
  }
  return "";
}

// Einheitliche spielKey-Berechnung (identisch in EinsätzeView, Kalender, Function).
function spielKeyFromSpiel(s){
  return `${s.datum}_${s.mannschaft}_${normName(s.gegner)}`.replace(/[.#$/\[\]]/g,"_");
}

// Der Anzeigename einer Person, wie er als Betreuer/Fahrer gespeichert wird: "Vorname Nachname".
function personAnzeigeName(player){
  if(!player) return "";
  return `${(player.firstName||"").trim()} ${(player.lastName||"").trim()}`.trim();
}

// Prüft, ob die Person als Betreuer (1 oder 2) dieses Spiels eingetragen ist.
// einsaetzeData: {spielKey:{_betreuer1,_betreuer2,_fahrer}}. Vergleich normalisiert,
// damit Leerzeichen-/Punkt-Unterschiede nicht stören.
function personIstBetreuer(player, spiel, einsaetzeData){
  if(!player||!spiel||!einsaetzeData) return false;
  const eigen=normName(personAnzeigeName(player));
  if(!eigen) return false;
  const ei=einsaetzeData[spielKeyFromSpiel(spiel)]||{};
  return normName(ei._betreuer1||"")===eigen || normName(ei._betreuer2||"")===eigen;
}

// Wochentag-Kurzform (2 Buchstaben) aus ISO-Datum
const EINSATZ_TAGE=["So","Mo","Di","Mi","Do","Fr","Sa"];
function wochentagKurz(isoDatum){
  const d=new Date(isoDatum+"T12:00:00");
  return isNaN(d.getTime())?"":EINSATZ_TAGE[d.getDay()];
}

// Erlaubte Mannschaften je nach Rolle (gibt Aufstellungs-Namen zurück)
function erlaubteMannschaften({player, roles, isAdmin, aufstellungSpieler, allTeams}){
  if(isAdmin || roles?.admin) return allTeams; // Admin: alle
  const result=new Set();
  // Trainer: alle Nachwuchsmannschaften
  if(roles?.trainer){ allTeams.filter(istNachwuchsMannschaft).forEach(t=>result.add(t)); }
  // Mannschaftsführer: seine Mannschaft(en) — aus mannschaftsfuehrerTeam + mfClickTT.
  // Der hinterlegte Wert kann in verschiedenen Schreibweisen vorliegen (z.B. „Herren 6"
  // aus dem Spielplan, „Erwachsene VI" aus der Aufstellung, oder der Alt-Wert
  // „Erwachsene" für die 1.). Wir normalisieren jeden Wert auf den Aufstellungs-Namen
  // und gleichen ihn dann mit allTeams ab, damit die Zuordnung zuverlässig greift.
  if(roles?.mannschaftsfuehrer && player){
    const mfTeams=[player.mannschaftsfuehrerTeam, ...(player.mfClickTT||[])].filter(Boolean);
    for(const mt of mfTeams){
      const roh=(mt||"").trim();
      // Kandidaten-Schreibweisen bilden und die erste in allTeams passende übernehmen.
      const kand = [
        SPIELPLAN_TO_AUFSTELLUNG[roh],  // „Herren 6" → „Erwachsene VI"
        normAufName(roh),               // „Erwachsene" → „Erwachsene I", sonst unverändert
        roh,                            // getrimmter Rohwert
      ].filter(Boolean);
      // 1) exakter Treffer, 2) Treffer ohne Rücksicht auf Groß/Klein & Leerzeichen
      let treffer = kand.find(k=>allTeams.includes(k));
      if(!treffer){
        const norm=s=>(s||"").toLowerCase().replace(/\s+/g,"");
        treffer = allTeams.find(a=> kand.some(k=>norm(k)===norm(a)));
      }
      if(treffer) result.add(treffer);
    }
  }
  // Spieler selbst: eigene gemeldete Mannschaften + (bei Erwachsenen) alle höheren
  if(player){
    const own=teamsOfPlayer(player, aufstellungSpieler);
    for(const t of own){
      if(istErwachsenenMannschaft(t)){
        const n=ERW_NUM[normAufName(t)];
        for(const [name,num] of Object.entries(ERW_NUM)){
          if(num<=n && allTeams.includes(name)) result.add(name);
        }
      } else {
        result.add(t);
      }
    }
  }
  return allTeams.filter(t=>result.has(t));
}

const EINSATZ_OPTS = [
  {key:"ja",       label:"Ja",       icon:"✅", color:"#10b981"},
  {key:"nein",     label:"Nein",     icon:"❌", color:"#ef4444"},
  {key:"vielleicht",label:"Vielleicht",icon:"❓", color:"#f59e0b"},
  {key:"verletzt", label:"Verletzt", icon:"🤕", color:"#8b5cf6"},
];

// Prüft, ob eine Aufstellungszeile den NES-Status trägt (Nachwuchs-Ergänzungsspieler).
// bem kann mehrere Kürzel enthalten (z.B. "gA, NES"); wir prüfen tokenweise.
function zeileHatNES(row){
  if(!row||!row.bem) return false;
  return String(row.bem).split(/[\s,]+/).map(t=>t.trim()).includes("NES");
}

// FAHRER-KANDIDATEN (nur Auswärts, Nachwuchs):
// Eltern der Kinder OHNE NES-Status in dieser Mannschaft. Alle gepflegten
// Elternteile ("Vorname Nachname"), Duplikate zusammengefasst, alphabetisch
// nach Vorname. Ein Kind gilt als "ohne NES", wenn seine Aufstellungszeile in
// genau dieser Mannschaft KEIN NES trägt.
function fahrerKandidaten(selTeam, players, aufSpieler){
  if(!selTeam) return [];
  const namen=new Set();
  // Kinder dieser Mannschaft ohne NES ermitteln
  for(const row of aufSpieler){
    if(row.mannschaft!==selTeam) continue;
    if(zeileHatNES(row)) continue; // NES-Kinder ausschließen
    // zugehörige Person finden (für Elternfelder)
    const kind = players.find(p=>playerMatchesAufName(p,row.name));
    if(!kind) continue;
    const paare=[
      [kind.elternVorname1, kind.elternNachname1],
      [kind.elternVorname2, kind.elternNachname2],
    ];
    for(const [vn,nn] of paare){
      const v=(vn||"").trim(), n=(nn||"").trim();
      if(v||n) namen.add(`${v} ${n}`.trim());
    }
  }
  return [...namen].sort((a,b)=>a.localeCompare(b,"de"));
}

// BETREUER-KANDIDATEN (Nachwuchs, Heim & Auswärts):
// Trainer + aktive Erwachsene, dedupliziert, alphabetisch nach Vorname,
// OHNE Trainer, die selbst laut Aufstellung in DIESER Mannschaft stehen.
function betreuerKandidaten(selTeam, players, aufSpieler){
  const map=new Map(); // key "Vorname Nachname" -> label
  for(const p of players){
    if(p.status==="passiv") continue;
    const istTrainer = p.roles?.trainer===true;
    const istErwachsene = p.roles?.erwachsene===true || (p.group==="Erwachsene");
    if(!istTrainer && !istErwachsene) continue;
    // Trainer, die selbst in dieser Mannschaft aufgestellt sind, ausschließen
    if(istTrainer && teamsOfPlayer(p, aufSpieler).includes(selTeam)) continue;
    const vn=(p.firstName||"").trim(), nn=(p.lastName||"").trim();
    const label=`${vn} ${nn}`.trim();
    if(label) map.set(label, {label, vn});
  }
  return [...map.values()].sort((a,b)=>a.vn.localeCompare(b.vn,"de")).map(x=>x.label);
}

function EinsaetzeView({ players, myPlayer, isAdmin, roles, viewerCanEditAll }) {
  const [spielplaene,setSpielplaene] = useState({});
  const [aufstellungen,setAufstellungen] = useState({});
  const [einsaetze,setEinsaetze] = useState({});
  const [selSeasonId,setSelSeasonId] = useState("spielplan_2026_2027");
  const [selTeam,setSelTeam] = useState("");
  const [expandedGames,setExpandedGames] = useState({}); // {spielKey: true} — aufgeklappte Spieltage

  const SEASON_OPTS = [
    {id:"spielplan_2026_2027", label:"2026/27", auf:"aufstellung_2026_2027_V"},
    {id:"spielplan_2025_2026", label:"2025/26", auf:"aufstellung_2025_2026_R"},
  ];

  useEffect(()=>{
    const unsubs=[];
    for(const so of SEASON_OPTS){
      unsubs.push(onSnapshot(doc(db,"config",so.id),snap=>{
        const data = snap.exists()&&(snap.data().spiele||[]).length>0
          ? snap.data().spiele : (SPIELPLAN_DATA[so.id]||[]);
        setSpielplaene(p=>({...p,[so.id]:data}));
      },()=>{ setSpielplaene(p=>({...p,[so.id]:SPIELPLAN_DATA[so.id]||[]})); }));
      unsubs.push(onSnapshot(doc(db,"config",so.auf),snap=>{
        const data = snap.exists()&&(snap.data().spieler||[]).length>0
          ? snap.data().spieler : (AUFSTELLUNG_DATA[so.auf]||[]);
        setAufstellungen(p=>({...p,[so.auf]:data}));
      },()=>{ setAufstellungen(p=>({...p,[so.auf]:AUFSTELLUNG_DATA[so.auf]||[]})); }));
    }
    return ()=>unsubs.forEach(u=>u());
  },[]);

  useEffect(()=>{
    const unsub=onSnapshot(doc(db,"einsaetze",selSeasonId),snap=>{
      setEinsaetze(snap.exists()?(snap.data().data||{}):{});
    },()=>setEinsaetze({}));
    return unsub;
  },[selSeasonId]);

  // Aus einer Einsätze-Map das datensparsame Betreuer/Fahrer-Spiegelobjekt bauen.
  function buildBetreuerFahrerSpiegel(quelle){
    const bf={};
    for(const k in quelle){
      const e=quelle[k]||{};
      const b1=e._betreuer1||"", b2=e._betreuer2||"", f=e._fahrer||"";
      if(b1||b2||f) bf[k]={b1,b2,f};
    }
    return bf;
  }

  // Einmaliger Abgleich: sorgt dafür, dass bereits erfasste Betreuer/Fahrer im
  // öffentlichen Spiegeldokument landen, auch wenn sie vor diesem Update oder ohne
  // erfolgreiches Spiegel-Schreiben gesetzt wurden. Läuft nur, wenn der Betrachter
  // schreibberechtigt ist und der Spiegel tatsächlich vom Soll abweicht.
  const spiegelSyncRef=useRef("");
  useEffect(()=>{
    if(!viewerCanEditAll) return;                 // nur Trainer/MF/Admin lösen den Abgleich aus
    if(Object.keys(einsaetze).length===0) return; // noch nichts geladen
    const soll=buildBetreuerFahrerSpiegel(einsaetze);
    if(Object.keys(soll).length===0) return;      // nichts zu spiegeln
    const syncKey=selSeasonId+"|"+JSON.stringify(soll);
    if(spiegelSyncRef.current===syncKey) return;  // schon abgeglichen
    spiegelSyncRef.current=syncKey;
    (async()=>{
      try{
        const ref=doc(db,"config",`betreuerFahrer_${selSeasonId}`);
        const snap=await getDoc(ref);
        const ist=snap.exists()?(snap.data().data||{}):{};
        if(JSON.stringify(ist)!==JSON.stringify(soll)){
          await setDoc(ref,{data:soll,lastUpdated:Date.now()});
        }
      }catch(e){}
    })();
  },[einsaetze,selSeasonId,viewerCanEditAll]);

  const curSeasonOpt = SEASON_OPTS.find(s=>s.id===selSeasonId)||SEASON_OPTS[0];
  const spiele = spielplaene[selSeasonId]||[];
  const aufSpieler = aufstellungen[curSeasonOpt.auf]||[];
  // Aufstellungsdaten führen die 1. Mannschaft teils noch als "Erwachsene" (ohne
  // Ziffer). Für die einheitliche Anzeige/Filterung auf "Erwachsene I" normalisieren.
  const allTeams = [...new Set(aufSpieler.map(r=>normAufName(r.mannschaft)))];

  const allowed = erlaubteMannschaften({player:myPlayer, roles, isAdmin, aufstellungSpieler:aufSpieler, allTeams});

  // Bevorzugte Vorauswahl: die Mannschaft, in der die Person gemeldet ist.
  // Bei Erwachsenen ist die Person in genau EINER Mannschaft gemeldet und darf
  // in höheren als Ersatz spielen → die gemeldete Mannschaft ist die mit der
  // höchsten Nummer. Primär über Aufstellungs-Match; falls der Name nicht sauber
  // matcht, zuverlässiger Fallback über die erlaubten Mannschaften (deren höchste
  // Nummer = eigene Meldung, da "eigene + höhere" erlaubt sind).
  const eigeneMannschaft = (()=>{
    if(!myPlayer) return null;
    // Stamm-Mannschaft bevorzugen: bei Erwachsenen die tiefste gemeldete, beim
    // Nachwuchs die Mannschaft OHNE NES-Status (nicht die Ergänzungs-Meldungen).
    // Nur Mannschaften berücksichtigen, die auch erlaubt/sichtbar sind.
    const ohneNES = teamsOfPlayerOhneNES(myPlayer, aufSpieler).filter(t=>allowed.includes(t));
    const ohneNESErw = ohneNES.filter(istErwachsenenMannschaft);
    if(ohneNESErw.length>0) return ohneNESErw.sort((a,b)=>ERW_NUM[normAufName(b)]-ERW_NUM[normAufName(a)])[0];
    const ohneNESNw = ohneNES.filter(istNachwuchsMannschaft);
    if(ohneNESNw.length>0) return ohneNESNw[0]; // Nachwuchs-Stammmannschaft (ohne NES)
    if(ohneNES.length>0) return ohneNES[0];

    // Fallback (keine NES-freie Meldung gefunden): wie bisher über alle Meldungen.
    const own = teamsOfPlayer(myPlayer, aufSpieler).filter(t=>allowed.includes(t));
    const ownErw = own.filter(istErwachsenenMannschaft);
    if(ownErw.length>0) return ownErw.sort((a,b)=>ERW_NUM[normAufName(b)]-ERW_NUM[normAufName(a)])[0]; // tiefste gemeldete
    if(own.length>0) return own[0]; // Nachwuchs
    const allowedErw = allowed.filter(istErwachsenenMannschaft);
    if(allowedErw.length>0) return allowedErw.sort((a,b)=>ERW_NUM[normAufName(b)]-ERW_NUM[normAufName(a)])[0];
    return allowed[0]||null;
  })();

  const lastKeyRef = useRef("");
  useEffect(()=>{
    if(allowed.length===0){ setSelTeam(""); lastKeyRef.current=""; return; }
    const target = (eigeneMannschaft && allowed.includes(eigeneMannschaft)) ? eigeneMannschaft : allowed[0];
    const key = `${selSeasonId}|${myPlayer?.id||""}`;
    if(lastKeyRef.current !== key){
      // Spieler oder Saison gewechselt → gemeldete Mannschaft neu wählen
      lastKeyRef.current = key;
      setSelTeam(target);
    } else if(!allowed.includes(selTeam)){
      // gleiche Person, aber aktuelle Auswahl nicht mehr gültig
      setSelTeam(target);
    }
  },[selSeasonId, allowed.join("|"), eigeneMannschaft, myPlayer?.id]);

  const teamSpiele = spiele.filter(s=>{
    const aufName = normAufName(SPIELPLAN_TO_AUFSTELLUNG[s.mannschaft]||s.mannschaft);
    return aufName===normAufName(selTeam);
  }).sort((a,b)=>a.datum.localeCompare(b.datum));

  const spielberechtigt = (()=>{
    if(!selTeam) return [];
    const result=[];
    for(const p of players){
      if(p.status==="passiv") continue;
      const own = teamsOfPlayer(p, aufSpieler);
      let ok=false;
      if(istErwachsenenMannschaft(selTeam)){
        const target=ERW_NUM[normAufName(selTeam)];
        for(const t of own){ if(istErwachsenenMannschaft(t) && ERW_NUM[normAufName(t)]>=target){ ok=true; break; } }
      } else {
        ok = own.includes(selTeam);
      }
      if(ok){
        // Rang aus der eigenen (gemeldeten) Mannschaft — bei Hochspielern bleibt z.B. "5.2"
        let rang="";
        if(istErwachsenenMannschaft(selTeam)){
          // tiefste eigene Erwachsenen-Mannschaft (höchste Nummer)
          let bestNum=-1;
          for(const t of own){ if(istErwachsenenMannschaft(t)&&ERW_NUM[normAufName(t)]>bestNum){bestNum=ERW_NUM[normAufName(t)]; rang=rangOfPlayerInTeam(p,t,aufSpieler);} }
        } else {
          rang=rangOfPlayerInTeam(p,selTeam,aufSpieler);
        }
        result.push({...p, _rang:rang});
      }
    }
    // nach Rang sortieren (numerisch: "2.3" → 2.03)
    const rv=r=>{const m=(r||"").split(".");return m.length===2?parseInt(m[0])*100+parseInt(m[1]):9999;};
    result.sort((a,b)=>rv(a._rang)-rv(b._rang));
    return result;
  })();

  function spielKey(s){ return `${s.datum}_${s.mannschaft}_${normName(s.gegner)}`.replace(/[.#$/\[\]]/g,"_"); }

  // Betreuer/Fahrer nur für Nachwuchsmannschaften. Kandidatenlisten hängen nur
  // von selTeam/Aufstellung/Personen ab → einmal pro Team berechnen.
  const selTeamIstNachwuchs = selTeam ? istNachwuchsMannschaft(selTeam) : false;
  const fahrerListe   = selTeamIstNachwuchs ? fahrerKandidaten(selTeam, players, aufSpieler) : [];
  const betreuerListe = selTeamIstNachwuchs ? betreuerKandidaten(selTeam, players, aufSpieler) : [];

  function canEdit(targetPlayerId){
    if(viewerCanEditAll) return true;
    return myPlayer && targetPlayerId===myPlayer.id;
  }

  async function setStatus(spiel, targetPlayerId, statusKey){
    const sk=spielKey(spiel);
    const cur = einsaetze[sk]||{};
    const prevEntry = cur[targetPlayerId]||{};
    const vorherStatus = prevEntry.status||"";
    const newEntry = (prevEntry.status===statusKey)
      ? {...prevEntry, status:""}
      : {...prevEntry, status:statusKey};
    const nachherStatus = newEntry.status||"";
    const updated = {...einsaetze, [sk]:{...cur, [targetPlayerId]:newEntry}};
    setEinsaetze(updated);
    try { await setDoc(doc(db,"einsaetze",selSeasonId),{data:updated,lastUpdated:Date.now()},{merge:true}); } catch(e){}

    // Sofort-Benachrichtigung an MF + Admin, wenn ein Spieler von "verfügbar" (ja)
    // auf einen anderen Status wechselt. Bewusst NUR in diesem Fall (nicht beim
    // erstmaligen Eintrag und nicht bei Wechsel ZU "ja").
    if(vorherStatus==="ja" && nachherStatus!=="ja"){
      try{
        const sp = players.find(p=>p.id===targetPlayerId);
        const spielerName = sp ? `${sp.firstName||""} ${sp.lastName||""}`.trim() : "Ein Spieler";
        // Der Spielplan nutzt Namen wie "Herren 2", das MF-Feld (mannschaftsfuehrerTeam)
        // dagegen den Aufstellungs-Namen wie "Erwachsene II". Für die MF-Zuordnung den
        // Namen übersetzen; für die Anzeige bleibt der (bekannte) Spielplan-Name erhalten.
        const spielplanName = spiel.mannschaft||"";
        const aufstellungName = SPIELPLAN_TO_AUFSTELLUNG[spielplanName] || spielplanName;
        fetch("/.netlify/functions/einsatzalarm",{
          method:"POST",
          headers:{"Content-Type":"application/json"},
          body: JSON.stringify({
            spielerName,
            mannschaft: spielplanName,          // für die Anzeige in der Meldung
            mannschaftAufstellung: aufstellungName, // für die MF-Zuordnung (mannschaftsfuehrerTeam)
            gegner: spiel.gegner||"",
            datum: spiel.datum||"",
            alterStatus: "ja",
            neuerStatus: nachherStatus
          })
        }).catch(()=>{}); // Fehler hier darf die Statusänderung nicht blockieren
      }catch(e){ /* Benachrichtigung ist Zusatz */ }
    }
  }
  async function setNote(spiel, targetPlayerId, note){
    const sk=spielKey(spiel);
    const cur = einsaetze[sk]||{};
    const prevEntry = cur[targetPlayerId]||{};
    const updated = {...einsaetze, [sk]:{...cur, [targetPlayerId]:{...prevEntry,note}}};
    setEinsaetze(updated);
    try { await setDoc(doc(db,"einsaetze",selSeasonId),{data:updated,lastUpdated:Date.now()},{merge:true}); } catch(e){}
  }
  // Betreuer/Fahrer sind spiel-global (nicht pro Spieler). Gespeichert unter
  // einsaetze[sk] mit den Schlüsseln _betreuer1/_betreuer2/_fahrer. Sofort speichern.
  async function setEinsatzFeld(spiel, feld, wert){
    const sk=spielKey(spiel);
    const cur = einsaetze[sk]||{};
    const updated = {...einsaetze, [sk]:{...cur, [feld]:wert}};
    setEinsaetze(updated);
    try { await setDoc(doc(db,"einsaetze",selSeasonId),{data:updated,lastUpdated:Date.now()},{merge:true}); } catch(e){}
    // Zusätzlich das datensparsame, öffentlich lesbare Spiegeldokument pflegen,
    // aus dem der Kalender-Abo-Feed (Netlify-Function) ohne Login liest.
    // Doc: config/betreuerFahrer_{saison}. Ein Fehler hier wird gemeldet, damit ein
    // fehlendes Regel-Deployment o.ä. nicht unbemerkt bleibt.
    try {
      const bf=buildBetreuerFahrerSpiegel(updated);
      await setDoc(doc(db,"config",`betreuerFahrer_${selSeasonId}`),{data:bf,lastUpdated:Date.now()});
    } catch(e){
      console.error("Betreuer/Fahrer-Spiegel konnte nicht gespeichert werden:",e);
      if(typeof window!=="undefined") window.alert(
        "Hinweis: Betreuer/Fahrer wurden gespeichert, konnten aber nicht für das Kalender-Abo veröffentlicht werden.\n\n"+
        "Mögliche Ursache: die aktualisierten Firestore-Regeln sind noch nicht in der Firebase Console deployt.\n\n"+
        "Details: "+(e?.message||e)
      );
    }
  }

  const heuteStr=new Date().toLocaleDateString("sv");

  // ── Finale Nominierung durch den Mannschaftsführer (Anf. 1) ──────────────────
  // Pro Spieltag wird unter einsaetze[sk]._nominiert ein Array der endgültig
  // aufgestellten Spieler-IDs gehalten. Nur MF/Trainer/Admin (viewerCanEditAll)
  // dürfen nominieren. Die Liste ist für alle Spieler der Mannschaft sichtbar (Anf. 2)
  // und steuert später den Punktspiel-Push (Anf. 3).
  async function toggleNominiert(spiel, targetPlayerId){
    if(!viewerCanEditAll) return;
    const sk=spielKey(spiel);
    const cur = einsaetze[sk]||{};
    const bisher = Array.isArray(cur._nominiert)?cur._nominiert:[];
    const drin = bisher.includes(targetPlayerId);
    const neu = drin ? bisher.filter(x=>x!==targetPlayerId) : [...bisher, targetPlayerId];
    const updated = {...einsaetze, [sk]:{...cur, _nominiert:neu}};
    setEinsaetze(updated);
    try { await setDoc(doc(db,"einsaetze",selSeasonId),{data:updated,lastUpdated:Date.now()},{merge:true}); } catch(e){}
  }

  // Wer darf Betreuer/Fahrer setzen? Admin/Trainer/MF (viewerCanEditAll) sowie
  // Eltern (über den Kind-Account) und Erwachsene für sich — praktisch jeder, der
  // dieses Spiel in seiner Einsätze-Sicht sieht. Reine Nur-Lese-Fälle gibt es hier
  // nicht, daher an viewerCanEditAll ODER vorhandenem myPlayer festmachen.
  const kannBetreuerFahrer = !!(viewerCanEditAll || myPlayer);

  // Anf.2: Block mit der finalen Aufstellung – für ALLE Spieler der Mannschaft sichtbar.
  function nominierungsBlock(spiel){
    const sk=spielKey(spiel);
    const cur=einsaetze[sk]||{};
    const ids=Array.isArray(cur._nominiert)?cur._nominiert:[];
    if(ids.length===0){
      if(!viewerCanEditAll) return null;   // Spieler sehen erst etwas, wenn nominiert wurde
      return <div style={{marginTop:8,paddingTop:8,borderTop:"1px dashed var(--border2)",fontSize:11,color:"var(--text4)"}}>
        Noch keine finale Aufstellung festgelegt. Mit ⭐ die endgültig aufgestellten Spieler markieren.
      </div>;
    }
    const nameVonId=(id)=>{ const p=(players||[]).find(x=>x.id===id); return p?`${p.firstName} ${p.lastName}`:null; };
    const geordnet=[
      ...spielberechtigt.filter(p=>ids.includes(p.id)).map(p=>`${p.firstName} ${p.lastName}`),
      ...ids.filter(id=>!spielberechtigt.some(p=>p.id===id)).map(nameVonId).filter(Boolean),
    ];
    return <div style={{marginTop:8,paddingTop:8,borderTop:"1px dashed var(--border2)"}}>
      <div style={{fontSize:10,fontWeight:700,color:"#f59e0b",marginBottom:4,textTransform:"uppercase",letterSpacing:0.3}}>⭐ Finale Aufstellung ({geordnet.length})</div>
      <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
        {geordnet.map((nm,i)=><span key={i} style={{fontSize:12,fontWeight:600,color:"var(--text)",background:"#f59e0b18",border:"1px solid #f59e0b44",borderRadius:7,padding:"3px 9px"}}>{nm}</span>)}
      </div>
    </div>;
  }

  // Rendert den Betreuer-/Fahrer-Block für ein Nachwuchsspiel.
  function betreuerFahrerBlock(spiel){
    if(!selTeamIstNachwuchs) return null;
    const sk=spielKey(spiel);
    const cur=einsaetze[sk]||{};
    const istHeim=(spiel.ort==="Heim");
    const editable=kannBetreuerFahrer;
    const selStyle={padding:"5px 8px",fontSize:12,borderRadius:7,background:"var(--bg)",
      border:"1px solid var(--border2)",color:"var(--text)",minWidth:0,flex:"1 1 140px",maxWidth:"100%"};
    const labelStyle={fontSize:10,fontWeight:700,color:"var(--text3)",marginBottom:3,textTransform:"uppercase",letterSpacing:0.3};
    const feld=(feldKey,wert,liste,placeholder)=>(
      <div style={{flex:"1 1 140px",minWidth:0}}>
        <select value={wert||""} disabled={!editable}
          onChange={e=>setEinsatzFeld(spiel,feldKey,e.target.value)}
          style={{...selStyle,opacity:editable?1:0.6,cursor:editable?"pointer":"default",width:"100%"}}>
          <option value="">{placeholder}</option>
          {/* aktuell gespeicherter Wert bleibt wählbar, auch wenn nicht mehr in der Liste */}
          {wert&&!liste.includes(wert)&&<option value={wert}>{wert}</option>}
          {liste.map(n=><option key={n} value={n}>{n}</option>)}
        </select>
      </div>
    );
    return <div style={{marginTop:8,paddingTop:8,borderTop:"1px dashed var(--border2)"}}>
      <div style={{display:"flex",flexWrap:"wrap",gap:10}}>
        {/* Betreuer: Heim 2 Felder, Auswärts 1 Feld */}
        <div style={{flex:"2 1 220px",minWidth:0}}>
          <div style={labelStyle}>🧑‍🏫 Betreuer</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {feld("_betreuer1",cur._betreuer1,betreuerListe,istHeim?"Betreuer 1 …":"Betreuer …")}
            {istHeim&&feld("_betreuer2",cur._betreuer2,betreuerListe,"Betreuer 2 …")}
          </div>
        </div>
        {/* Fahrer nur bei Auswärtsspielen */}
        {!istHeim&&<div style={{flex:"1 1 160px",minWidth:0}}>
          <div style={labelStyle}>🚗 Fahrer</div>
          <div style={{display:"flex",gap:8}}>
            {feld("_fahrer",cur._fahrer,fahrerListe,"Fahrer …")}
          </div>
          {fahrerListe.length===0&&<div style={{fontSize:10,color:"var(--text4)",marginTop:3}}>Keine Eltern-Namen hinterlegt.</div>}
        </div>}
      </div>
    </div>;
  }

  return <div style={{padding:13,paddingBottom:40}}>
    <div style={{fontSize:17,fontWeight:800,marginBottom:8}}>🗓️ Einsätze</div>

    <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:12}}>
      <select value={selSeasonId} onChange={e=>setSelSeasonId(e.target.value)}
        style={{padding:"7px 10px",borderRadius:8,fontSize:13,fontWeight:700,background:"var(--bg2)",border:"1px solid var(--border2)",color:"var(--text)"}}>
        {SEASON_OPTS.map(s=><option key={s.id} value={s.id}>{s.label}{s.id==="spielplan_2026_2027"?" (aktuell)":""}</option>)}
      </select>
      <select value={selTeam} onChange={e=>setSelTeam(e.target.value)}
        style={{padding:"7px 10px",borderRadius:8,fontSize:13,fontWeight:700,background:"var(--bg2)",border:"1px solid var(--border2)",color:"var(--text)",flex:1,minWidth:140}}>
        {allowed.length===0&&<option value="">Keine Mannschaft verfügbar</option>}
        {allowed.map(t=><option key={t} value={t}>{t}</option>)}
      </select>
    </div>

    {allowed.length===0&&<div style={{padding:24,textAlign:"center",color:"var(--text3)",fontSize:13}}>
      Für deine Rolle sind aktuell keine Mannschaften hinterlegt.
    </div>}

    {selTeam&&teamSpiele.length===0&&<div style={{padding:24,textAlign:"center",color:"var(--text3)",fontSize:13}}>
      Keine Spiele für {selTeam} in dieser Saison gefunden.
    </div>}

    {viewerCanEditAll&&selTeam&&teamSpiele.length>0&&<div style={{display:"flex",gap:8,marginBottom:10}}>
      <button onClick={()=>{
        const all={}; teamSpiele.forEach(s=>{all[spielKey(s)]=true;}); setExpandedGames(g=>({...g,...all}));
      }} style={{padding:"5px 10px",borderRadius:7,fontSize:11,fontWeight:600,background:"var(--bg3)",border:"1px solid var(--border2)",color:"var(--text2)",cursor:"pointer"}}>▼ Alle aufklappen</button>
      <button onClick={()=>{
        const all={...expandedGames}; teamSpiele.forEach(s=>{all[spielKey(s)]=false;}); setExpandedGames(all);
      }} style={{padding:"5px 10px",borderRadius:7,fontSize:11,fontWeight:600,background:"var(--bg3)",border:"1px solid var(--border2)",color:"var(--text2)",cursor:"pointer"}}>▶ Alle zuklappen</button>
    </div>}

    {selTeam&&teamSpiele.map(spiel=>{
      const sk=spielKey(spiel);
      const entries=einsaetze[sk]||{};
      const past = spiel.datum < heuteStr;
      const counts={ja:0,nein:0,vielleicht:0,verletzt:0};
      spielberechtigt.forEach(p=>{ const st=entries[p.id]?.status; if(st&&counts[st]!=null) counts[st]++; });
      const tag=wochentagKurz(spiel.datum);
      // Welche Spieler-Zeilen werden gezeigt?
      // Admin/Trainer/MF (viewerCanEditAll): alle spielberechtigten.
      // Spieler/Erwachsene: nur die eigene Zeile (falls spielberechtigt).
      const rows = viewerCanEditAll
        ? spielberechtigt
        : spielberechtigt.filter(p=>myPlayer && p.id===myPlayer.id);
      // Aufklappen nur in der Voll-Sicht (Admin/Trainer/MF); Spieler sehen ihre Zeile immer.
      const isOpen = viewerCanEditAll ? !!expandedGames[sk] : true;
      const showRows = isOpen;
      // Self-View (Spieler/Erwachsene): eigener Eintrag für Inline-Buttons im Kopf
      const selfPlayer = !viewerCanEditAll ? rows[0] : null;
      const selfEntry = selfPlayer ? (entries[selfPlayer.id]||{}) : null;
      const selfEditable = selfPlayer ? canEdit(selfPlayer.id) : false;
      return <div key={sk} style={{background:"var(--bg2)",borderRadius:12,border:"1px solid var(--border)",marginBottom:12,overflow:"hidden",opacity:past?0.7:1}}>
        <div onClick={viewerCanEditAll?()=>setExpandedGames(g=>({...g,[sk]:!g[sk]})):undefined}
          style={{padding:"10px 12px",borderBottom:(viewerCanEditAll&&showRows&&rows.length)?"1px solid var(--border)":"none",
            background:"var(--bg3)",cursor:viewerCanEditAll?"pointer":"default"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,flexWrap:"wrap"}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              {viewerCanEditAll&&<span style={{fontSize:12,color:"var(--text3)",transform:isOpen?"rotate(90deg)":"none",transition:"transform .15s",display:"inline-block"}}>▶</span>}
              <div>
                <div style={{fontSize:13,fontWeight:700,color:"var(--text)"}}>
                  {tag&&<span style={{color:"var(--text3)"}}>{tag} </span>}
                  {spiel.datum.split("-").reverse().join(".")} · {spiel.uhrzeit} Uhr
                </div>
                <div style={{fontSize:12,color:"var(--text2)",display:"flex",alignItems:"center",gap:5}}>
                  {spiel.art==="Pokal" && <span title="Pokalspiel" style={{flexShrink:0}}>🏆</span>}
                  <span>{spiel.ort} vs. {spiel.gegner}</span>
                </div>
              </div>
            </div>
            {/* Voll-Sicht: Zählung. Self-View: die 4 Buttons direkt im Kopf. */}
            {viewerCanEditAll&&<div style={{display:"flex",gap:6,fontSize:11,fontWeight:700,flexShrink:0}}>
              <span style={{color:"#10b981"}}>✅{counts.ja}</span>
              <span style={{color:"#ef4444"}}>❌{counts.nein}</span>
              <span style={{color:"#f59e0b"}}>❓{counts.vielleicht}</span>
              <span style={{color:"#8b5cf6"}}>🤕{counts.verletzt}</span>
            </div>}
            {!viewerCanEditAll&&selfPlayer&&<div style={{display:"flex",gap:4,flexShrink:0}}>
              {EINSATZ_OPTS.map(opt=>{
                const active=selfEntry.status===opt.key;
                return <button key={opt.key} disabled={!selfEditable}
                  onClick={()=>selfEditable&&setStatus(spiel,selfPlayer.id,opt.key)}
                  title={opt.label}
                  style={{padding:"4px 7px",borderRadius:7,fontSize:13,
                    border:`1.5px solid ${active?opt.color:"var(--border2)"}`,
                    background:active?opt.color+"22":"transparent",
                    cursor:selfEditable?"pointer":"default",opacity:selfEditable?1:0.5}}>
                  {opt.icon}
                </button>;
              })}
            </div>}
          </div>
        </div>
        {/* Self-View ohne Spielberechtigung: Hinweis */}
        {!viewerCanEditAll&&!selfPlayer&&<div style={{padding:"8px 12px 10px",fontSize:12,color:"var(--text4)"}}>Für dieses Spiel bist du nicht spielberechtigt.</div>}
        {/* Voll-Sicht: Spielerliste (aufklappbar) */}
        {viewerCanEditAll&&showRows&&<div style={{padding:rows.length?"6px 10px 10px":"0"}}>
          {spielberechtigt.length===0&&<div style={{fontSize:12,color:"var(--text4)",padding:"8px 0"}}>Keine spielberechtigten Spieler gefunden.</div>}
          {rows.map(p=>{
            const entry=entries[p.id]||{};
            const editable=canEdit(p.id);
            const isMe = myPlayer && p.id===myPlayer.id;
            return <div key={p.id} style={{padding:"7px 0",borderBottom:"1px solid var(--border)"}}>
              <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                <span style={{fontSize:13,fontWeight:isMe?700:500,color:isMe?"var(--text)":"var(--text2)",minWidth:120,flex:1}}>
                  {p._rang&&<span style={{color:"var(--text4)",fontWeight:700,marginRight:5}}>{p._rang}</span>}
                  {p.avatar||"🏓"} {p.firstName} {p.lastName}{isMe?" (ich)":""}
                </span>
                {/* Anf.1: finale Nominierung durch MF/Trainer/Admin */}
                {(()=>{
                  const nominiert=(entries._nominiert||[]).includes(p.id);
                  return <button onClick={()=>toggleNominiert(spiel,p.id)} title={nominiert?"Nominierung entfernen":"Für dieses Spiel nominieren"}
                    style={{padding:"4px 8px",borderRadius:7,fontSize:13,fontWeight:700,cursor:"pointer",
                      border:`1.5px solid ${nominiert?"#f59e0b":"var(--border2)"}`,
                      background:nominiert?"#f59e0b22":"transparent",color:nominiert?"#f59e0b":"var(--text3)"}}>
                    {nominiert?"⭐":"☆"}
                  </button>;
                })()}
                <div style={{display:"flex",gap:4}}>
                  {EINSATZ_OPTS.map(opt=>{
                    const active=entry.status===opt.key;
                    return <button key={opt.key} disabled={!editable}
                      onClick={()=>editable&&setStatus(spiel,p.id,opt.key)}
                      title={opt.label}
                      style={{padding:"4px 7px",borderRadius:7,fontSize:13,
                        border:`1.5px solid ${active?opt.color:"var(--border2)"}`,
                        background:active?opt.color+"22":"transparent",
                        cursor:editable?"pointer":"default",opacity:editable?1:0.5}}>
                      {opt.icon}
                    </button>;
                  })}
                </div>
              </div>
              {(editable||entry.note)&&<input
                value={entry.note||""} disabled={!editable}
                onChange={e=>setNote(spiel,p.id,e.target.value)}
                placeholder="Notiz (optional)…"
                style={{marginTop:5,width:"100%",padding:"5px 8px",fontSize:11,
                  background:"var(--bg)",border:"1px solid var(--border2)",borderRadius:6,
                  color:"var(--text2)",outline:"none"}}/>}
            </div>;
          })}
          {betreuerFahrerBlock(spiel)}
          {nominierungsBlock(spiel)}
        </div>}
        {/* Self-View (Spieler/Erwachsene/Eltern): finale Aufstellung + ggf. Betreuer/Fahrer */}
        {!viewerCanEditAll&&selfPlayer&&<div style={{padding:"0 12px 10px"}}>
          {selTeamIstNachwuchs&&betreuerFahrerBlock(spiel)}
          {nominierungsBlock(spiel)}
        </div>}
      </div>;
    })}
  </div>;
}

function SpielbetrieblTab({isSuperAdmin}) {
  const [teamPhotos,setTeamPhotos] = useState({});
  const [teamFiles,setTeamFiles] = useState({});
  const [uploadingFor,setUploadingFor] = useState(null);
  // Saison-Auswahl: standardmäßig die aktuelle Saison
  const [selSeasonKey,setSelSeasonKey] = useState((SEASONS.find(s=>s.current)||SEASONS[0]).key);
  const season = SEASONS.find(s=>s.key===selSeasonKey) || SEASONS[0];
  const seasonTeams = season.teams;

  useEffect(()=>{
    const u1 = onSnapshot(doc(db,"config","teamPhotos"),snap=>{
      if(snap.exists()) setTeamPhotos(snap.data());
    },()=>{});
    const u2 = onSnapshot(doc(db,"config","teamFiles"),snap=>{
      if(snap.exists()) setTeamFiles(snap.data());
    },()=>{});
    return ()=>{u1();u2();};
  },[]);

  async function handlePhotoUpload(teamId, file) {
    if (!file) return;
    setUploadingFor(teamId);
    const reader = new FileReader();
    reader.onload = async (e) => {
      const dataUrl = e.target.result;
      const updated = {...teamPhotos, [teamId]: dataUrl};
      await setDoc(doc(db,"config","teamPhotos"), updated, {merge:true}).catch(()=>{});
      setTeamPhotos(updated);
      setUploadingFor(null);
    };
    reader.readAsDataURL(file);
  }

  const LinkBtn = ({href,label,icon}) => (
    <a href={href} target="_blank" rel="noopener noreferrer" style={{
      display:"inline-flex",alignItems:"center",gap:4,
      padding:"5px 9px",borderRadius:7,fontSize:11,fontWeight:600,
      background:"var(--bg3)",border:"1px solid var(--border2)",
      color:"var(--text2)",textDecoration:"none",
      whiteSpace:"nowrap",
    }}>{icon} {label}</a>
  );

  return <div style={{padding:13,paddingBottom:40}}>
    <div style={{fontSize:17,fontWeight:800,marginBottom:8}}>📋 Spielbetrieb</div>

    {/* Saison-Auswahl */}
    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:12}}>
      <span style={{fontSize:12,color:"var(--text3)"}}>Saison:</span>
      <select value={selSeasonKey} onChange={e=>setSelSeasonKey(e.target.value)}
        style={{padding:"6px 10px",borderRadius:8,fontSize:13,fontWeight:700,
          background:"var(--bg2)",border:"1px solid var(--border2)",color:"var(--text)"}}>
        {SEASONS.map(s=><option key={s.key} value={s.key}>{s.key}{s.current?" (aktuell)":""}</option>)}
      </select>
    </div>

    <div style={{fontSize:11,color:"var(--text3)",marginBottom:14}}>
      TTC Niederzeuzheim · Saison {season.key} · Hessischer Tischtennis-Verband
      {!season.showStandings&&<span style={{color:"#f59e0b"}}> · Platzierungen noch nicht verfügbar</span>}
    </div>

    <div style={{display:"grid",gridTemplateColumns:"1fr",gap:12}}>
      {seasonTeams.map(t=>{
        const links = teamLinks(t, season.code);
        const photo = teamPhotos[t.id];
        const hasStandings = season.showStandings && t.rang!=null;
        const showLinks = season.showLinks && t.gruppe;
        return <div key={t.id} style={{
          background:"var(--bg2)",borderRadius:14,overflow:"hidden",
          border:`1px solid var(--border)`,
          borderLeft:`4px solid ${t.color}`,
        }}>
          {/* Team header */}
          <div style={{display:"flex",alignItems:"stretch",minHeight:80}}>
            {/* Photo area */}
            <div style={{
              width:90,flexShrink:0,background:photo?"transparent":"var(--bg3)",
              display:"flex",alignItems:"center",justifyContent:"center",
              position:"relative",overflow:"hidden",
            }}>
              {photo
                ? <img src={photo} alt={t.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>
                : <span style={{fontSize:28}}>🏓</span>
              }
              {isSuperAdmin&&<label style={{
                position:"absolute",bottom:0,left:0,right:0,
                background:"rgba(0,0,0,0.55)",color:"#fff",
                fontSize:9,textAlign:"center",padding:"3px 0",cursor:"pointer",
              }}>
                {uploadingFor===t.id?"⏳":photo?"📷 ändern":"📷 Foto"}
                <input type="file" accept="image/*" style={{display:"none"}}
                  onChange={e=>handlePhotoUpload(t.id, e.target.files?.[0])}
                  disabled={uploadingFor===t.id}/>
              </label>}
            </div>

            {/* Team info */}
            <div style={{flex:1,padding:"10px 12px"}}>
              <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:3}}>
                <div style={{fontSize:14,fontWeight:800,color:t.color}}>{t.name}</div>
                {hasStandings&&<div style={{
                  fontSize:11,fontWeight:700,
                  color:t.rang<=3?"#10b981":t.rang<=6?"#f59e0b":"var(--text3)",
                  background:t.rang<=3?"#10b98122":t.rang<=6?"#f59e0b22":"var(--bg3)",
                  padding:"2px 7px",borderRadius:20,
                }}>Platz {t.rang}</div>}
              </div>
              {t.liga&&<div style={{fontSize:11,color:"var(--text3)",marginBottom:6}}>{t.liga}</div>}
              {hasStandings
                ? <div style={{fontSize:11,color:"var(--text2)"}}>Punkte: <b style={{color:"var(--text)"}}>{t.punkte}</b></div>
                : <div style={{fontSize:11,color:"var(--text4)",fontStyle:"italic"}}>Saison läuft noch — Tabelle siehe Links</div>}
            </div>
          </div>

          {/* Links — bei Saisons mit veröffentlichten Liga-/Gruppendaten */}
          {showLinks&&<div style={{padding:"8px 12px 10px",borderTop:"1px solid var(--border)",display:"flex",gap:6,flexWrap:"wrap"}}>
            <LinkBtn href={links.tabelle}    label="Tabelle"    icon="📊"/>
            <LinkBtn href={links.spielplan}  label="Spielplan"  icon="📅"/>
            <LinkBtn href={links.aufstellung} label="Aufstellung" icon="👥"/>
            <LinkBtn href={links.einzelrl}   label="Einzel-RL"  icon="🥇"/>
            <LinkBtn href={links.doppelrl}   label="Doppel-RL"  icon="🥈"/>
            {(()=>{
              const slug=selSeasonKey.replace("/","_");
              const dataUrl=teamFiles[`${slug}_${t.id}_pin`] ?? teamFiles[`${t.id}_pin`];
              if(!dataUrl) return null;
              const name=teamFiles[`${slug}_${t.id}_pin_name`] ?? teamFiles[`${t.id}_pin_name`] ?? "spiel-pins";
              const isPdf=dataUrl.startsWith("data:application/pdf")||name.endsWith(".pdf");
              if(isPdf){
                return <button onClick={()=>{
                  const blob=dataURLtoBlob(dataUrl);
                  const url=URL.createObjectURL(blob);
                  window.open(url,"_blank");
                }} style={{display:"inline-flex",alignItems:"center",gap:4,padding:"5px 9px",borderRadius:7,fontSize:11,fontWeight:600,background:"var(--bg3)",border:"1px solid var(--border2)",color:"var(--text2)",cursor:"pointer"}}>🔑 Spiel-PINs</button>;
              }
              return <a href={dataUrl} target="_blank" rel="noopener noreferrer" download={name}
                style={{display:"inline-flex",alignItems:"center",gap:4,padding:"5px 9px",borderRadius:7,fontSize:11,fontWeight:600,background:"var(--bg3)",border:"1px solid var(--border2)",color:"var(--text2)",textDecoration:"none",cursor:"pointer"}}>🔑 Spiel-PINs</a>;
            })()}
            {(()=>{
              const slug=selSeasonKey.replace("/","_");
              const dataUrl=teamFiles[`${slug}_${t.id}_code`] ?? teamFiles[`${t.id}_code`];
              if(!dataUrl) return null;
              const name=teamFiles[`${slug}_${t.id}_code_name`] ?? teamFiles[`${t.id}_code_name`] ?? "spielcodes";
              const isPdf=dataUrl.startsWith("data:application/pdf")||name.endsWith(".pdf");
              if(isPdf){
                return <button onClick={()=>{
                  const blob=dataURLtoBlob(dataUrl);
                  const url=URL.createObjectURL(blob);
                  window.open(url,"_blank");
                }} style={{display:"inline-flex",alignItems:"center",gap:4,padding:"5px 9px",borderRadius:7,fontSize:11,fontWeight:600,background:"var(--bg3)",border:"1px solid var(--border2)",color:"var(--text2)",cursor:"pointer"}}>🎫 Spielcodes</button>;
              }
              return <a href={dataUrl} target="_blank" rel="noopener noreferrer" download={name}
                style={{display:"inline-flex",alignItems:"center",gap:4,padding:"5px 9px",borderRadius:7,fontSize:11,fontWeight:600,background:"var(--bg3)",border:"1px solid var(--border2)",color:"var(--text2)",textDecoration:"none",cursor:"pointer"}}>🎫 Spielcodes</a>;
            })()}
          </div>}
        </div>;
      })}
    </div>

    {/* Link to full overview */}
    <a href={`${BASE}/10--11/${CLUB}/mannschaften`} target="_blank" rel="noopener noreferrer"
      style={{display:"block",marginTop:16,textAlign:"center",fontSize:12,color:"#3b82f6",textDecoration:"none"}}>
      🌐 Alle Mannschaften auf myTischtennis.de →
    </a>
  </div>;
}



